W, H = A4[0] - 4*cm, A4[1] - 5.5*cm
def img(name, maxh=H*0.72):
    w, hh = PI.open(D + name).size
    s = min(W / w, maxh / hh)
    return Image(D + name, w*s, hh*s)

n = [0]
def fig(name, title, maxh=H*0.72):
    n[0] += 1
    return KeepTogether([img(name, maxh), Paragraph(f"Рис. {n[0]}. {title}", cap)])

